// Minimal shadcn-style primitives. In production, generated by the
// shadcn CLI; these stubs match the API so the imports are stable.
import { forwardRef, type ButtonHTMLAttributes } from 'react'

export const Button = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'default' | 'outline' | 'ghost' }>(
  function Button({ className = '', variant = 'default', ...rest }, ref) {
    const base = 'inline-flex items-center justify-center rounded text-sm font-medium transition-colors disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[hsl(var(--ring))]'
    const variants = {
      default: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:opacity-90 px-3 py-1.5',
      outline: 'border bg-transparent hover:bg-[hsl(var(--accent))] px-3 py-1.5',
      ghost: 'hover:bg-[hsl(var(--accent))] px-2 py-1',
    } as const
    return <button ref={ref} className={`${base} ${variants[variant]} ${className}`} {...rest} />
  },
)
